-- Lote 4/4: 25 questões expert por obra (50 no total).
WITH incoming AS (
  SELECT * FROM jsonb_to_recordset($questions$[{"book":"livro_espiritos","statement":"A questão 27 afirma que há três elementos gerais no Universo. Qual interpretação preserva a distinção apresentada por Kardec?","option_a":"Deus é a causa primária; Espírito e matéria são elementos gerais distintos, sem que a matéria seja reduzida ao pensamento.","option_b":"Deus e matéria são os únicos elementos, sendo o Espírito uma ilusão.","option_c":"Espírito e perispírito são os elementos gerais, enquanto Deus é uma hipótese.","option_d":"Matéria e princípio vital são idênticos, e o Espírito é uma propriedade orgânica.","option_e":"Espírito é apenas matéria em estado rarefeito.","correct_option":"A","explanation":"A resposta distingue Deus como causa primária e Espírito e matéria como elementos gerais, evitando confundir o princípio inteligente com a substância material.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. II, questão 27.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual é a consequência lógica da escala espírita para a compreensão da desigualdade moral entre os indivíduos?","option_a":"As diferenças morais provam que alguns Espíritos foram criados superiores.","option_b":"A escala descreve estados de progresso de seres de mesma origem, não castas espirituais imutáveis.","option_c":"A posição social determina a ordem espiritual.","option_d":"O conhecimento intelectual é o único critério de classificação.","option_e":"A evolução ocorre apenas depois da morte.","correct_option":"B","explanation":"A escala espírita organiza diferenças de adiantamento moral entre Espíritos de origem comum e em processo de progresso.","reference":"O Livro dos Espíritos, Livro Segundo, cap. I, questões 96–113.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Como conciliar a escolha das provas com a existência de acontecimentos que não parecem escolhidos pelo indivíduo?","option_a":"A escolha prévia significa controle consciente de cada detalhe da encarnação.","option_b":"A existência de imprevistos invalida a liberdade espiritual.","option_c":"A escolha das provas envolve objetivos e condições gerais de progresso, sem significar domínio absoluto de todos os eventos.","option_d":"Todo acontecimento é uma punição individual.","option_e":"A liberdade só existe antes do nascimento.","correct_option":"C","explanation":"A obra trata a escolha das provas em termos de necessidades e objetivos de progresso, não como previsão e controle de cada circunstância.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VI, questões 258–273.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual interpretação é mais coerente com a relação entre esquecimento do passado e responsabilidade moral?","option_a":"O esquecimento extingue toda responsabilidade anterior.","option_b":"O esquecimento prova que não há continuidade do Espírito.","option_c":"A responsabilidade depende apenas da memória consciente.","option_d":"A ausência de lembrança explícita não elimina a continuidade moral nem as oportunidades de reparar e progredir.","option_e":"O passado determina mecanicamente todas as escolhas atuais.","correct_option":"D","explanation":"A obra apresenta o esquecimento como condição favorável à nova existência, sem negar a continuidade do Espírito e suas necessidades de progresso.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VII, questões 392–399.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Na doutrina da progressão, por que a imperfeição moral não é apresentada como condição definitiva?","option_a":"Porque todos os Espíritos são destinados ao progresso e podem desenvolver-se por esforço e experiência.","option_b":"Porque as imperfeições são apenas aparentes.","option_c":"Porque a evolução ocorre automaticamente, sem participação do Espírito.","option_d":"Porque somente a instrução intelectual corrige a moral.","option_e":"Porque a liberdade impede qualquer transformação.","correct_option":"A","explanation":"A obra sustenta a progressão dos Espíritos e a possibilidade de aperfeiçoamento, sem fixar a imperfeição como destino eterno.","reference":"O Livro dos Espíritos, Livro Segundo, cap. I, questões 114–118.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual é o cuidado metodológico implícito na resposta de Kardec sobre a influência dos Espíritos nos pensamentos?","option_a":"Atribuir todo pensamento a uma entidade espiritual.","option_b":"Negar a possibilidade de influência espiritual.","option_c":"Distinguir influência possível de determinação absoluta, preservando o exame e a responsabilidade do indivíduo.","option_d":"Aceitar qualquer intuição como comunicação infalível.","option_e":"Considerar que somente médiuns recebem influência.","correct_option":"C","explanation":"O capítulo reconhece a influência espiritual, mas não autoriza transformar toda ideia em comunicação nem retirar do indivíduo a responsabilidade.","reference":"O Livro dos Espíritos, Livro Segundo, cap. IX, questões 459–472.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Como a afinidade espiritual pode explicar vínculos que não coincidem com parentesco biológico?","option_a":"A afinidade depende exclusivamente de herança genética.","option_b":"Relações de simpatia e tendências morais podem unir Espíritos independentemente dos laços corporais de uma existência.","option_c":"O parentesco biológico é sempre ilusório.","option_d":"A afinidade só existe entre Espíritos puros.","option_e":"A afeição é determinada apenas pela convivência atual.","correct_option":"B","explanation":"A obra diferencia vínculos espirituais e parentesco corporal, atribuindo importância às afinidades e relações construídas entre Espíritos.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VI, questões 291–303; Livro Terceiro, cap. VII.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual é a distinção mais precisa entre prova e expiação no contexto da obra?","option_a":"Ambas significam necessariamente punição imposta sem finalidade.","option_b":"Prova é sempre sofrimento físico; expiação é sempre sofrimento moral.","option_c":"Prova é uma experiência de desenvolvimento; expiação se relaciona à reparação de faltas, sem excluir aprendizado e progresso.","option_d":"Expiação ocorre apenas após a morte.","option_e":"Provas e expiações são conceitos sem relação com a justiça divina.","correct_option":"C","explanation":"A obra aborda provas e expiações como experiências ligadas ao progresso e à reparação, não como condenações arbitrárias ou sem finalidade.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VI, questões 258–273.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Por que a noção de mundos de diferentes condições não implica privilégio espiritual permanente?","option_a":"Porque os mundos são criados para castas imutáveis.","option_b":"Porque todos os Espíritos permanecem no mundo em que nasceram.","option_c":"Porque a condição material determina para sempre a evolução.","option_d":"Porque a progressão permite experiências em mundos diversos, conforme o adiantamento alcançado.","option_e":"Porque somente os Espíritos inferiores encarnam.","correct_option":"D","explanation":"A pluralidade dos mundos é articulada à progressão: as condições de existência correspondem a estágios, não a privilégios eternos.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. III, questões 55–58; Livro Segundo, cap. IV.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual é o alcance moral da afirmação de que a lei natural está inscrita na consciência?","option_a":"A consciência torna desnecessário qualquer esforço de discernimento.","option_b":"A lei natural é conhecida de modo perfeito por todos desde o nascimento.","option_c":"A consciência é criada exclusivamente pelas leis civis.","option_d":"Há uma referência interior ao bem, mas o conhecimento e a prática podem exigir desenvolvimento e esclarecimento.","option_e":"A lei natural só se aplica a pessoas instruídas.","correct_option":"D","explanation":"A obra relaciona a lei natural à consciência, reconhecendo que sua compreensão e aplicação dependem do desenvolvimento do Espírito.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. I, questões 621–628.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Como a obra diferencia intenção moral e resultado material na avaliação de uma ação?","option_a":"O resultado material é o único critério válido.","option_b":"A intenção sincera é relevante, mas não transforma automaticamente uma ação danosa em boa; o dever inclui discernimento e responsabilidade.","option_c":"A intenção elimina toda consequência.","option_d":"O reconhecimento público define o mérito.","option_e":"A ação não tem importância se a pessoa se considera bondosa.","correct_option":"B","explanation":"A avaliação moral considera intenção e consciência, mas não dispensa a responsabilidade pelo modo de agir e seus efeitos.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. X, questões 629–646.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual é a implicação social da lei de igualdade diante das diferenças de capacidades e condições?","option_a":"As diferenças justificam direitos morais desiguais.","option_b":"A igualdade exige que todos tenham as mesmas funções.","option_c":"A igualdade essencial não elimina diferenças de aptidões, mas impede que elas justifiquem a negação da dignidade e dos direitos.","option_d":"A desigualdade econômica é prova de mérito espiritual.","option_e":"A lei de igualdade vale apenas no mundo espiritual.","correct_option":"C","explanation":"A obra distingue igualdade natural e diversidade de condições, sem legitimar privilégios morais permanentes.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. IX, questões 803–824.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Por que o capítulo sobre a lei de destruição distingue processos naturais de atos humanos abusivos?","option_a":"Porque a transformação natural participa da renovação da vida, enquanto a crueldade e o excesso revelam escolhas morais humanas.","option_b":"Porque toda destruição humana é necessária.","option_c":"Porque a natureza não está sujeita a leis.","option_d":"Porque a intenção humana nunca importa.","option_e":"Porque a destruição é sempre um bem.","correct_option":"A","explanation":"A obra reconhece a destruição necessária à renovação natural e distingue dela os abusos resultantes de crueldade ou interesses humanos.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VI, questões 728–735.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual é a consequência ética da ideia de progresso contínuo para a compreensão da justiça?","option_a":"A justiça deve punir sem oferecer novas oportunidades.","option_b":"A reparação é impossível depois de uma falta.","option_c":"A justiça divina combina responsabilidade com oportunidades de reajuste e progresso, em vez de condenação eterna.","option_d":"O progresso elimina as consequências dos atos.","option_e":"A evolução dispensa a reparação.","correct_option":"C","explanation":"A pluralidade das existências e a progressão permitem compreender a justiça como responsabilidade acompanhada de oportunidades de reparação.","reference":"O Livro dos Espíritos, Livro Segundo, cap. IV; Livro Quarto, cap. II.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Como interpretar a afirmação de que a caridade é mais ampla que a beneficência material?","option_a":"Como rejeição da ajuda concreta.","option_b":"Como obrigação de doar apenas dinheiro.","option_c":"Como preferência por rituais religiosos.","option_d":"Como princípio que abrange benevolência, indulgência, perdão e auxílio efetivo conforme a necessidade.","option_e":"Como uma virtude restrita à vida privada.","correct_option":"D","explanation":"A definição de caridade inclui atitudes interiores e relações cotidianas, sem excluir a assistência material quando necessária.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. XI, questão 886.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual é a leitura mais consistente da relação entre liberdade e influência espiritual?","option_a":"A influência espiritual pode sugerir ou estimular, mas não torna o indivíduo mero instrumento sem responsabilidade.","option_b":"Toda influência espiritual elimina o livre-arbítrio.","option_c":"O indivíduo é responsável apenas quando não recebe influência.","option_d":"Somente os Espíritos inferiores influenciam escolhas.","option_e":"A liberdade impede qualquer intercâmbio espiritual.","correct_option":"A","explanation":"A obra concilia influência espiritual e liberdade, atribuindo ao indivíduo responsabilidade pelo acolhimento e pela escolha de seus atos.","reference":"O Livro dos Espíritos, Livro Segundo, cap. IX, questões 459–472.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Por que a instrução intelectual isolada não garante progresso moral?","option_a":"Porque o conhecimento é sempre prejudicial.","option_b":"Porque a moral é determinada apenas pela hereditariedade.","option_c":"Porque o saber pode crescer sem que orgulho, egoísmo e paixões sejam superados.","option_d":"Porque a inteligência e a moral são incompatíveis.","option_e":"Porque o progresso moral depende somente de fenômenos mediúnicos.","correct_option":"C","explanation":"A obra distingue progresso intelectual e moral e indica que o desenvolvimento completo exige transformação das tendências e da conduta.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VIII, questões 780–785.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual é o sentido mais profundo da lei de sociedade na perspectiva do aperfeiçoamento espiritual?","option_a":"A convivência serve apenas para garantir sobrevivência física.","option_b":"As relações sociais oferecem oportunidades de cooperação, aprendizado, exercício da caridade e correção das próprias imperfeições.","option_c":"O isolamento é a condição natural dos Espíritos.","option_d":"A sociedade impede a liberdade moral.","option_e":"A vida social é necessária somente aos Espíritos inferiores.","correct_option":"B","explanation":"A lei de sociedade é apresentada como necessidade natural e campo de desenvolvimento das virtudes e da solidariedade.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VII, questões 766–772.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Como a obra permite compreender o arrependimento sem transformá-lo em mecanismo automático de absolvição?","option_a":"O arrependimento apaga o passado sem consequências.","option_b":"O arrependimento não tem qualquer valor.","option_c":"O arrependimento é o início da mudança, mas a reparação e a transformação da conduta continuam necessárias.","option_d":"A reparação é impossível após a morte.","option_e":"Basta declarar arrependimento para alcançar a perfeição.","correct_option":"C","explanation":"A obra trata o arrependimento como começo do reajuste, que deve prosseguir por meio de expiação, reparação e esforço moral.","reference":"O Livro dos Espíritos, Livro Quarto, cap. II, questões 990–1002.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual é a consequência da ideia de que a evolução espiritual não ocorre por privilégio de nascimento?","option_a":"A posição social pode indicar o grau espiritual com certeza.","option_b":"A origem familiar determina o destino moral.","option_c":"A instrução formal garante superioridade espiritual.","option_d":"O progresso depende do desenvolvimento do Espírito, não de títulos, riqueza ou linhagem.","option_e":"A condição material define a ordem na escala espírita.","correct_option":"D","explanation":"A obra fundamenta a progressão no aperfeiçoamento do Espírito, não em privilégios sociais ou hereditários.","reference":"O Livro dos Espíritos, Livro Segundo, cap. I; Livro Terceiro, cap. IX.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Por que a liberdade de consciência é coerente com o progresso moral?","option_a":"Porque a convicção moral deve amadurecer pelo esclarecimento e pela escolha, não pela imposição violenta.","option_b":"Porque toda opinião é igualmente verdadeira.","option_c":"Porque a consciência não precisa de educação.","option_d":"Porque a sociedade não pode estabelecer regras de convivência.","option_e":"Porque a liberdade elimina a responsabilidade.","correct_option":"A","explanation":"A obra valoriza a liberdade e o desenvolvimento da consciência, sem confundi-los com ausência de responsabilidade.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. X, questões 835–842.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Como a pluralidade das existências contribui para uma interpretação não fatalista das desigualdades?","option_a":"Transforma diferenças em privilégios permanentes.","option_b":"Explica diferenças como etapas e circunstâncias de uma trajetória mais ampla, preservando a possibilidade de progresso e a responsabilidade presente.","option_c":"Determina que cada pessoa permaneça na condição atual.","option_d":"Elimina a necessidade de justiça social.","option_e":"Prova que o sofrimento alheio deve ser ignorado.","correct_option":"B","explanation":"A reencarnação oferece uma perspectiva de continuidade e progresso, sem justificar indiferença ou negar os deveres de solidariedade.","reference":"O Livro dos Espíritos, Livro Segundo, cap. IV; Livro Terceiro, caps. VII e IX.","difficulty":"expert","active":true},{"book":"livro_espiritos","statement":"Qual é a implicação da questão 625 ao apresentar Jesus como modelo e guia da humanidade?","option_a":"A imitação deve limitar-se a ritos externos.","option_b":"O exemplo de Jesus substitui a consciência individual.","option_c":"A referência moral deve orientar a conduta concreta, especialmente no amor, na justiça e na caridade.","option_d":"A perfeição é alcançada apenas pela admiração verbal.","option_e":"O modelo é inacessível e não deve ser seguido.","correct_option":"C","explanation":"A obra indica Jesus como modelo moral, cuja vida e ensinamentos oferecem referência prática para o aperfeiçoamento humano.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. I, questão 625.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é o fundamento epistemológico do controle universal apresentado na introdução?","option_a":"A autoridade exclusiva de um revelador individual.","option_b":"A repetição de uma mensagem dentro de um único grupo.","option_c":"A concordância espontânea e independente entre comunicações de muitos médiuns, em locais diversos, examinada pela razão.","option_d":"A aceitação de qualquer mensagem que cite Jesus.","option_e":"A superioridade automática de comunicações antigas.","correct_option":"C","explanation":"Kardec apresenta a concordância independente como garantia doutrinária, complementada pelo exame racional e pela coerência dos princípios.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção II.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Por que a introdução distingue princípios doutrinários de comunicações sobre assuntos secundários ao explicar o controle universal?","option_a":"Porque qualquer detalhe comunicado por um médium deve ser universalizado.","option_b":"Porque a concordância relevante se refere aos princípios fundamentais, não a opiniões isoladas ou questões secundárias.","option_c":"Porque assuntos secundários são sempre falsos.","option_d":"Porque a doutrina depende de previsões individuais.","option_e":"Porque a razão não pode examinar questões práticas.","correct_option":"B","explanation":"A introdução delimita o controle universal aos princípios da doutrina, evitando transformar comunicações particulares em fundamentos gerais.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção II.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Como a obra articula o ensino moral do Cristo e a diversidade de tradições religiosas?","option_a":"A moral evangélica é apresentada como terreno comum de conduta, acima de controvérsias dogmáticas particulares.","option_b":"A diversidade religiosa torna impossível qualquer princípio moral comum.","option_c":"A obra exige adesão a uma instituição específica.","option_d":"A moral depende exclusivamente de milagres.","option_e":"A tradição de cada grupo deve ser substituída por outra.","correct_option":"A","explanation":"A introdução destaca a moral como ponto de encontro entre diferentes crenças e como regra prática para a vida.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção I.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é a distinção hermenêutica central do capítulo I entre a lei divina e as prescrições humanas de uma época?","option_a":"Toda prescrição antiga é eterna e imutável.","option_b":"A lei divina é apenas uma convenção cultural.","option_c":"Jesus rejeita integralmente a tradição moral anterior.","option_d":"Os princípios divinos permanecem, enquanto certas prescrições humanas e interpretações circunstanciais podem ser superadas.","option_e":"A lei moral só vale para um povo.","correct_option":"D","explanation":"O capítulo distingue a permanência da lei divina das formas e prescrições humanas próprias de contextos históricos.","reference":"O Evangelho Segundo o Espiritismo, cap. I, itens 1–3.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é a consequência da interpretação reencarnacionista do diálogo com Nicodemos para a noção de justiça divina?","option_a":"A vida corporal é uma oportunidade entre outras para o progresso, e não a única chance absoluta do Espírito.","option_b":"A justiça divina depende da posição social de nascimento.","option_c":"A reencarnação elimina a responsabilidade individual.","option_d":"A vida espiritual começa apenas após a segunda encarnação.","option_e":"O novo nascimento é somente uma metáfora social.","correct_option":"A","explanation":"O capítulo IV utiliza a reencarnação para explicar a pluralidade das existências e as oportunidades de progresso espiritual.","reference":"O Evangelho Segundo o Espiritismo, cap. IV, itens 4–17.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Como o capítulo V evita que a explicação das aflições se converta em justificativa para a indiferença social?","option_a":"Afirma que o sofrimento deve ser observado sem interferência.","option_b":"Ensina que a compreensão das causas deve coexistir com solidariedade, auxílio e resignação ativa.","option_c":"Determina que toda dor seja mantida.","option_d":"Proíbe a assistência material.","option_e":"Afirma que somente o sofredor tem deveres morais.","correct_option":"B","explanation":"O capítulo aborda causas das aflições, mas mantém a caridade e o auxílio ao próximo como deveres fundamentais.","reference":"O Evangelho Segundo o Espiritismo, cap. V, itens 12–19.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é a relação entre o Consolador e a ideia de desenvolvimento progressivo do entendimento religioso?","option_a":"O Consolador anula os ensinamentos anteriores.","option_b":"O Consolador restringe a compreensão a uma elite.","option_c":"O Consolador esclarece, recorda e desenvolve o sentido dos ensinamentos de Jesus, favorecendo sua aplicação.","option_d":"O Consolador substitui a responsabilidade moral por fenômenos.","option_e":"O Consolador é uma autoridade política.","correct_option":"C","explanation":"O capítulo VI relaciona a promessa do Consolador ao esclarecimento dos ensinamentos e ao fortalecimento moral dos homens.","reference":"O Evangelho Segundo o Espiritismo, cap. VI, itens 3–8.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Por que a humildade do capítulo VII é incompatível com a presunção intelectual?","option_a":"Porque o conhecimento deve ser ocultado.","option_b":"Porque a humildade exige rejeitar a razão.","option_c":"Porque a presunção reconhece os próprios limites.","option_d":"Porque a presunção fecha o indivíduo à correção e ao aprendizado, enquanto a humildade reconhece a própria condição perfectível.","option_e":"Porque a humildade impede toda iniciativa.","correct_option":"D","explanation":"O capítulo critica o orgulho e apresenta a humildade como disposição para aprender e reconhecer as próprias imperfeições.","reference":"O Evangelho Segundo o Espiritismo, cap. VII, itens 1–2.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Como o capítulo X permite conciliar indulgência com a necessidade de combater o mal?","option_a":"A indulgência é autocrítica e compreensão, não aprovação do erro; pode coexistir com a proteção e a correção justa.","option_b":"A indulgência exige silêncio diante de violência.","option_c":"A indulgência proíbe qualquer consequência para atos prejudiciais.","option_d":"A correção deve ser sempre humilhante.","option_e":"O erro alheio deve ser exposto publicamente.","correct_option":"A","explanation":"A obra recomenda indulgência e exame de si mesmo, sem transformar perdão em omissão diante de danos.","reference":"O Evangelho Segundo o Espiritismo, cap. X, itens 11–13.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é a implicação do amor aos inimigos para a noção de justiça moral?","option_a":"A justiça deve ser abandonada.","option_b":"A pessoa deve aprovar o mal para demonstrar amor.","option_c":"O amor impede qualquer limite ou proteção.","option_d":"O amor rompe a vingança e o ódio, sem eliminar a necessidade de justiça e responsabilidade.","option_e":"A reconciliação deve ser imposta unilateralmente.","correct_option":"D","explanation":"O capítulo XII ensina a superar o ressentimento e desejar o bem, sem confundir isso com aprovação do mal.","reference":"O Evangelho Segundo o Espiritismo, cap. XII, itens 1–3.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Por que a caridade moral do capítulo XIII exige mais que discrição externa?","option_a":"Porque a discrição sozinha pode coexistir com vaidade; é necessário intenção desinteressada e respeito à dignidade de quem recebe.","option_b":"Porque a ajuda deve ser sempre anônima e impessoal.","option_c":"Porque a intenção não tem importância.","option_d":"Porque a caridade deve evitar qualquer vínculo humano.","option_e":"Porque a ajuda material é proibida.","correct_option":"A","explanation":"O capítulo valoriza a intenção e a dignidade do beneficiado, criticando a ostentação e o interesse pessoal.","reference":"O Evangelho Segundo o Espiritismo, cap. XIII, itens 1–3 e 9–10.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Como a distinção entre família corporal e espiritual modifica a compreensão dos deveres familiares?","option_a":"Elimina os deveres com os pais.","option_b":"Substitui o cuidado familiar por vínculos abstratos.","option_c":"Permite compreender afinidades e compromissos além do sangue, sem anular respeito, cuidado e gratidão na família atual.","option_d":"Torna o parentesco biológico irrelevante em qualquer circunstância.","option_e":"Determina que todos os familiares tenham afinidade imediata.","correct_option":"C","explanation":"O capítulo XIV amplia a reflexão sobre os laços familiares, distinguindo origem corporal e afinidade espiritual, mantendo os deveres de amor.","reference":"O Evangelho Segundo o Espiritismo, cap. XIV, itens 8–9.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é a crítica do capítulo XVI à riqueza quando ela se torna finalidade da existência?","option_a":"A riqueza é sempre condenável, qualquer que seja seu uso.","option_b":"O apego transforma os meios materiais em senhor da pessoa, desviando-a de valores morais e espirituais.","option_c":"A pobreza garante automaticamente elevação.","option_d":"O trabalho e a administração de recursos são condenados.","option_e":"A riqueza elimina toda oportunidade de progresso.","correct_option":"B","explanation":"O capítulo critica o apego a Mamon e orienta a utilizar os bens sem se tornar escravo deles.","reference":"O Evangelho Segundo o Espiritismo, cap. XVI, itens 1–3 e 7–9.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Como o capítulo XVII permite distinguir perfeição moral de perfeccionismo exterior?","option_a":"A perfeição moral depende de aparência sem falhas.","option_b":"O perfeccionismo exige julgar os demais.","option_c":"A perfeição moral é um processo de transformação interior que se manifesta em caridade, humildade e coerência, não em exibição.","option_d":"A perfeição significa nunca cometer um erro desde a infância.","option_e":"A perfeição é obtida por títulos religiosos.","correct_option":"C","explanation":"O capítulo orienta a busca das virtudes e da coerência moral, em oposição à aparência e à vaidade.","reference":"O Evangelho Segundo o Espiritismo, cap. XVII, itens 1–4.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é a leitura mais rigorosa da parábola do semeador em relação à responsabilidade do ouvinte?","option_a":"A mensagem é suficiente, independentemente da disposição de quem ouve.","option_b":"A responsabilidade pertence somente ao mensageiro.","option_c":"A compreensão é irrelevante para a prática.","option_d":"O ouvinte participa do resultado por sua receptividade, perseverança e capacidade de transformar o ensinamento em conduta.","option_e":"A parábola afirma que algumas pessoas não podem progredir.","correct_option":"D","explanation":"A parábola é aplicada às diferentes disposições diante da mensagem e à necessidade de fazê-la frutificar pela prática.","reference":"O Evangelho Segundo o Espiritismo, cap. XVIII, item 1.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Por que a fé raciocinada é apresentada como mais resistente que a crença baseada apenas em hábito?","option_a":"Porque pode compreender suas razões e enfrentar questionamentos sem depender de aceitação cega.","option_b":"Porque evita toda investigação.","option_c":"Porque dispensa coerência moral.","option_d":"Porque depende de fenômenos extraordinários.","option_e":"Porque nunca admite revisão de entendimento.","correct_option":"A","explanation":"O capítulo XIX valoriza a fé que pode encarar a razão em qualquer época, em vez de crença sustentada apenas por hábito ou temor.","reference":"O Evangelho Segundo o Espiritismo, cap. XIX, itens 6–7.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é a implicação ética da parábola dos trabalhadores da última hora para quem já possui experiência no bem?","option_a":"Pode desprezar quem começa depois.","option_b":"Deve competir por reconhecimento.","option_c":"Deve acolher novos trabalhadores sem inveja, reconhecendo a misericórdia e a finalidade comum do serviço.","option_d":"Pode considerar o tempo de serviço como privilégio absoluto.","option_e":"Deve impedir que outros participem.","correct_option":"C","explanation":"O capítulo interpreta a parábola como convite à humildade, ao serviço e à compreensão da justiça e bondade divinas.","reference":"O Evangelho Segundo o Espiritismo, cap. XX, itens 1–3.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Como o critério dos frutos, no capítulo XXI, protege contra a autoridade baseada apenas em carisma?","option_a":"A eloquência deve ser considerada prova suficiente.","option_b":"O carisma substitui a análise moral.","option_c":"A reputação torna desnecessário observar a conduta.","option_d":"A coerência entre ensinamento, caráter e efeitos morais é mais confiável que aparência ou prestígio.","option_e":"A autoridade deve ser aceita sem exame.","correct_option":"D","explanation":"O capítulo orienta a avaliar os frutos morais e a coerência, evitando confundir aparência impressionante com elevação espiritual.","reference":"O Evangelho Segundo o Espiritismo, cap. XXI, itens 1–3.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é a relação entre confiança na providência e esforço humano no capítulo XXV?","option_a":"A confiança torna o esforço desnecessário.","option_b":"A confiança sustenta a ação perseverante; buscar e bater implicam iniciativa e trabalho.","option_c":"O esforço humano demonstra falta de fé.","option_d":"A providência atende literalmente todo desejo.","option_e":"A ação só é válida quando há garantia de sucesso.","correct_option":"B","explanation":"O capítulo interpreta a busca como esforço ativo e persistente, não como espera passiva por resultados.","reference":"O Evangelho Segundo o Espiritismo, cap. XXV, itens 1–5.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Por que o capítulo XXVI condena a exploração comercial dos dons espirituais?","option_a":"Porque os dons são recebidos gratuitamente e devem servir ao bem, não ser convertidos em instrumento de lucro indevido.","option_b":"Porque todo trabalho deve ser gratuito.","option_c":"Porque o médium não possui responsabilidade sobre o uso de suas faculdades.","option_d":"Porque a mediunidade deve ser escondida.","option_e":"Porque a caridade depende de recompensa material.","correct_option":"A","explanation":"O capítulo aplica o princípio de dar gratuitamente o que gratuitamente se recebeu, criticando a exploração dos dons espirituais.","reference":"O Evangelho Segundo o Espiritismo, cap. XXVI, itens 1–2.","difficulty":"expert","active":true},{"book":"evangelho","statement":"Qual é o limite da prece em relação à vontade divina, conforme o capítulo XXVII?","option_a":"A prece pode obrigar Deus a conceder qualquer pedido.","option_b":"A prece substitui as leis naturais.","option_c":"A prece atua como elevação e pedido de força ou esclarecimento, sem impor a vontade humana à divina.","option_d":"A prece elimina a necessidade de reparar erros.","option_e":"A prece garante que terceiros mudem de atitude.","correct_option":"C","explanation":"O capítulo trata a prece como meio de elevação e auxílio, não como mecanismo de imposição de desejos.","reference":"O Evangelho Segundo o Espiritismo, cap. XXVII, itens 1–4.","difficulty":"expert","active":true}]$questions$::jsonb)
  AS x(book text, statement text, option_a text, option_b text, option_c text, option_d text, option_e text, correct_option text, explanation text, reference text, difficulty text, active boolean)
)
INSERT INTO public.questions (book, statement, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, reference, difficulty, active)
SELECT book, statement, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, reference, difficulty, active FROM incoming
ON CONFLICT (statement) DO NOTHING;
